// The Worker entry. It wraps the OpenNext handler to give every HTML response a fresh
// nonce and a strict content security policy, while the pages themselves stay static
// and cached. HTMLRewriter streams the page, so this costs well under a millisecond.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';
import { cspHeader, newNonce, securityHeaders } from './src/lib/security/csp';
import { ADMIN_AREA_HEADER, isAdminArea, viewAsRefusal, viewAsWriteRefused } from './src/lib/security/view-as-guard';
import { refreshSession } from './src/lib/auth/edge-refresh';
import { parseCookieHeader, readSession } from './src/lib/auth/session-cookie';
import { BEACON_GIVE_UP_MS, BEACON_WAIT_MS, BEAT_WAIT_MS, MAX_BEACON_BYTES, cleanBeacon, cleanBeat, emailLinkCookie, ipKey, isBeat, isBot, within } from './src/lib/track/shared';
import { SCHEMA_HEADER, SCHEMA_MARKER } from './src/lib/schema-marker';
import { EDGE_CACHE_NAME, deploymentOf, edgeKeep, edgeKey, edgeMatch, isProbe } from './src/lib/edge/page-cache';
import { jobsToRun } from './src/lib/edge/cron-gate';
import { FLEET_SIG_CONFIRM_KEY, FLEET_SIG_KEY, fleetRows, signatureOf } from './src/lib/edge/fleet-sig';
import { WARM_KEY, warmBatch, warmDone, warmPaths, warmValue } from './src/lib/edge/warm';
import { readNumber, writeNumber } from './src/lib/edge/page-cache';

/** The deployment last rebuilt for (a number from the Worker's version id), in the tag store next to the fleet's signature. */
const DEPLOY_SEEN_KEY = 'carmacars/deploy-seen';
function deployNumber(version: string | null): number {
  if (!version) return 0;
  let h = 0;
  for (let i = 0; i < version.length; i++) h = (Math.imul(h, 31) + version.charCodeAt(i)) | 0;
  return Math.abs(h) || 1;
}

type Env = Record<string, unknown>;

class NonceAdder {
  constructor(private readonly nonce: string) {}
  element(el: { setAttribute(name: string, value: string): void }) {
    el.setAttribute('nonce', this.nonce);
  }
}

interface PublicObject { body: ReadableStream; httpEtag: string; httpMetadata?: { contentType?: string } }
interface PublicBucket { get(key: string): Promise<PublicObject | null> }

// The public photo bucket (vehicle photos, site photos, logos) under /media when the site runs on
// the R2 bindings (STORAGE_PROVIDER=r2-binding, NEXT_PUBLIC_VEHICLE_PHOTOS_URL ending in /media).
async function media(request: Request, env: Env, path: string): Promise<Response> {
  const bucket = env.R2_VEHICLE_PUBLIC as PublicBucket | undefined;
  const key = decodeURIComponent(path.slice('/media/'.length));
  if (!bucket || !key || key.includes('..') || (request.method !== 'GET' && request.method !== 'HEAD')) return new Response('Not found', { status: 404 });
  const etag = request.headers.get('if-none-match');
  const o = await bucket.get(key);
  if (!o) return new Response('Not found', { status: 404, headers: { 'cache-control': 'public, max-age=60' } });
  const headers = new Headers({ 'content-type': o.httpMetadata?.contentType ?? 'application/octet-stream', etag: o.httpEtag,
    'cache-control': 'public, max-age=86400, stale-while-revalidate=604800', ...securityHeaders(),
    // a file opened directly (an SVG especially) can never run script on this origin
    'content-security-policy': "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox" });
  if (etag && etag === o.httpEtag) return new Response(null, { status: 304, headers });
  return new Response(request.method === 'HEAD' ? null : o.body, { headers });
}

// The listing worker's token: the same HMAC as src/server/listing-worker.ts (LINK_SIGNING_KEY, a fixed label).
async function workerToken(secret: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode('carmacars-listing-worker-v1')));
  return Array.from(mac, (b) => b.toString(16).padStart(2, '0')).join('');
}

// Live visitors (migration 0060): the site's beacon, answered here before the app is loaded, so a batch of page
// views costs well under a millisecond of the Worker's time and one call to the database. Bots are dropped; the city
// comes from Cloudflare; the network address only feeds a salted rate-limit key; the signed-in user's own token goes
// with the call (an expired one falls back to an anonymous call).
// 0103: the beacon never holds the browser. The database call runs under waitUntil; a batch waits for it at most
// 2 seconds (its answer can carry a staff invite to chat) and a heartbeat 1.5 seconds, then the Worker answers 204 and
// the call finishes in the background. The last batch of a page (pagehide, sendBeacon) is answered 204 at once, and
// its session is ended after its events are stored. A slow or failing database is a 204, never a 502.
async function track(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response | null> {
  const sbUrl = env.NEXT_PUBLIC_SUPABASE_URL, sbKey = env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (typeof sbUrl !== 'string' || typeof sbKey !== 'string' || !sbUrl) return null;
  const headers = { 'content-type': 'application/json', 'cache-control': 'no-store', ...securityHeaders() };
  const reply = (o: unknown, status = 200) => new Response(JSON.stringify(o), { status, headers });
  const none = () => new Response(null, { status: 204, headers: { 'cache-control': 'no-store', ...securityHeaders() } });
  const origin = request.headers.get('origin');
  if (origin && new URL(origin).host !== new URL(request.url).host) return reply({ ok: false }, 403);
  const ua = request.headers.get('user-agent');
  if (isBot(ua, env.TRACK_ALLOW_HEADLESS === '1')) return reply({ ok: true, bot: true });
  const text = await request.text();
  if (text.length > MAX_BEACON_BYTES) return reply({ ok: false }, 413);
  let raw: unknown;
  try { raw = JSON.parse(text); } catch { return reply({ ok: false }, 400); }
  const rpc = (fn: string, args: unknown, bearer: string) => fetch(`${sbUrl.replace(/\/$/, '')}/rest/v1/rpc/${fn}`, {
    method: 'POST', headers: { apikey: sbKey, authorization: `Bearer ${bearer}`, 'content-type': 'application/json' },
    body: JSON.stringify(args), signal: AbortSignal.timeout(BEACON_GIVE_UP_MS) });
  const background = <T>(p: Promise<T>) => { ctx.waitUntil(p.catch(() => undefined)); return p; };
  // the heartbeat of an open page: one UPDATE, anonymous (the session already says who it is)
  if (isBeat(raw)) {
    const beat = cleanBeat(raw);
    if (!beat) return reply({ ok: false }, 400);
    const p = background(rpc('track_beat', { p: beat }, sbKey).then(async (r) => (r.ok ? await r.text() : null)));
    if (beat.end) return none();
    const out = await within(p, BEAT_WAIT_MS);
    return out ? new Response(out, { status: 200, headers }) : none();
  }
  const b = cleanBeacon(raw, ua);
  if (!b) return reply({ ok: false }, 400);
  const { end, ...batch } = b;
  const cf = ((request as unknown as { cf?: Record<string, unknown> }).cf ?? {});
  const geo = { city: cf.city ?? null, region: cf.regionCode ?? null, country: cf.country ?? null,
    ip_key: await ipKey(request.headers.get('cf-connecting-ip'), sbKey.slice(-24)) };
  const token = readSession(parseCookieHeader(request.headers.get('cookie')))?.session.access_token;
  const ingest = async () => {
    let r = await rpc('track_ingest', { p: batch, p_geo: geo }, token ?? sbKey);
    if (token && (r.status === 401 || r.status === 403)) r = await rpc('track_ingest', { p: batch, p_geo: geo }, sbKey);
    const t = r.ok ? await r.text() : null;
    // the page closed: its session ends once its last events are in
    if (end) await rpc('track_beat', { p: { sid: b.sid, vid: b.vid, end: '1' } }, sbKey).then((x) => x.text());
    return t;
  };
  const p = background(ingest());
  if (end) return none();
  const out = await within(p, BEACON_WAIT_MS);
  return out ? new Response(out, { status: 200, headers }) : none();
}

// Turo by email (migration 0063): Cloudflare Email Routing hands every message sent to trips@in.carmacars.ca (a
// subdomain, so the root domain's Google Workspace mail is untouched) to this handler. The raw message goes to the app's
// /api/inbound/turo with the jobs' token; the app reads it and stores only the parsed fields. A message too large is
// refused; if the app cannot take it (the database is down), the handler throws, so the sender (Gmail) tries again.
interface InboundEmail { from: string; to: string; raw: ReadableStream; rawSize: number; setReject(reason: string): void }
const MAX_EMAIL_BYTES = 1_000_000;

const worker = {
  async email(message: InboundEmail, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<void> {
    const secret = typeof env.LINK_SIGNING_KEY === 'string' ? env.LINK_SIGNING_KEY : '';
    if (!secret) { message.setReject('Not set up'); return; }
    if (message.rawSize > MAX_EMAIL_BYTES) { message.setReject('Message too large'); return; }
    const base = typeof env.NEXT_PUBLIC_APP_URL === 'string' ? env.NEXT_PUBLIC_APP_URL : 'https://carmacars.ca';
    const raw = await new Response(message.raw).text();
    const r: Response = await handler.fetch(new Request(`${base.replace(/\/$/, '')}/api/inbound/turo`, {
      method: 'POST', body: raw,
      headers: { authorization: `Bearer ${await workerToken(secret)}`, 'content-type': 'message/rfc822', 'x-envelope-from': message.from, 'x-envelope-to': message.to }
    }), env, ctx);
    if (r.status === 413) { message.setReject('Message too large'); return; }
    if (!r.ok) throw new Error(`inbound email: the app answered ${r.status}`);
  },

  // Cloudflare cron trigger (wrangler.jsonc triggers.crons, every five minutes): the listing pipeline's
  // sweep and, hourly, the statement emails, through the app's own protected routes so they run with the
  // app's code and bindings.
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<void> {
    const secret = typeof env.LINK_SIGNING_KEY === 'string' ? env.LINK_SIGNING_KEY : '';
    if (!secret) return;
    const base = typeof env.NEXT_PUBLIC_APP_URL === 'string' ? env.NEXT_PUBLIC_APP_URL : 'https://carmacars.ca';
    const auth = { authorization: `Bearer ${await workerToken(secret)}` };
    const run = (path: string) => ctx.waitUntil(handler.fetch(new Request(`${base.replace(/\/$/, '')}${path}`, { method: 'POST', headers: auth }), env, ctx)
      .then((r: Response) => r.text()).catch(() => undefined));
    // only when the database has work for them (src/lib/edge/cron-gate.ts, 0076): an idle tick then never loads the app
    const due = await jobsToRun(env);
    if (due.listing) run('/api/jobs/listing');
    // the search copy (cars, landing pages, articles) and IndexNow (migration 0061)
    if (due.seo) run('/api/jobs/seo');
    // the phone line (migration 0085): booking texts that are due and the AI one-liners of calls
    if (due.phone) run('/api/jobs/phone');
    // a car put on or taken off the site in the database alone (0070's automatic publishing, a slug changed, a car
    // deleted): the fleet page, home, the model pages and the sitemaps are rebuilt (src/lib/edge/fleet-sig.ts)
    // (only with a tag store: pages served as built from the assets are never rebuilt)
    const self = env.WORKER_SELF_REFERENCE as { fetch(r: Request): Promise<Response> } | undefined;
    if (env.NEXT_TAG_CACHE_KV || env.NEXT_TAG_CACHE_D1) ctx.waitUntil((async () => {
      const [rows, seen, pending, deploySeen, warmed] = await Promise.all([fleetRows(env), readNumber(env, FLEET_SIG_KEY), readNumber(env, FLEET_SIG_CONFIRM_KEY), readNumber(env, DEPLOY_SEEN_KEY), readNumber(env, WARM_KEY)]);
      const sig = rows ? signatureOf(rows) : null;
      if (sig === null || seen === null) return;
      // after a change the pages are rebuilt twice, five minutes apart, so a page regenerated while the change was
      // being written cannot keep a stale list (the second pass is the confirm)
      const confirming = sig === seen && pending === sig;
      // the first tick after a deploy rebuilds them too: a page kept in the page cache by the previous build names that
      // build's style and script files, which are gone (the home page loaded without its styles on Oct 21)
      const deployed = deployNumber(deploymentOf(env));
      const newDeploy = deployed !== 0 && deploySeen !== deployed;
      let rebuiltForDeploy = !newDeploy;
      if (sig !== seen || confirming || newDeploy) {
        const r: Response = await handler.fetch(new Request(`${base.replace(/\/$/, '')}/api/jobs/public-rebuild`, { method: 'POST', headers: { ...auth, 'content-type': 'application/json' }, body: '{}' }), env, ctx);
        await r.text();
        if (r.ok) { await writeNumber(env, FLEET_SIG_KEY, sig); await writeNumber(env, FLEET_SIG_CONFIRM_KEY, confirming ? 0 : sig); if (newDeploy) { await writeNumber(env, DEPLOY_SEEN_KEY, deployed); rebuiltForDeploy = true; } }
      }
      // 0102: then the pages visitors open first are rendered once for this deploy (src/lib/edge/warm.ts): home, the fleet
      // page and each car page, through the service binding (each its own invocation), a few at a time within a budget;
      // the rest on the next ticks. Without it every car page was a cold render for its first visitor after a deploy.
      if (!rebuiltForDeploy || !self || deployed === 0 || warmed === null) return;
      const paths = warmPaths(rows!);
      const start = warmDone(warmed, deployed);
      if (start >= paths.length) return;
      const origin = base.replace(/\/$/, '');
      const done = await warmBatch(paths, start, async (path) => {
        const res = await self.fetch(new Request(`${origin}${path}`, { headers: { 'user-agent': 'CarmaCars warm-up (cron)', accept: 'text/html' } }));
        await res.arrayBuffer();
      });
      await writeNumber(env, WARM_KEY, warmValue(deployed, done));
    })().catch(() => undefined));
    // the monthly statement emails (PDF first), once an hour: the first tick of each hour
    if (new Date().getUTCMinutes() < 5) run('/api/jobs/statements');
    // signed copies waiting (0077): through the Worker's own service binding, so each run is its own invocation
    const pdfJobs = new Request(`${base.replace(/\/$/, '')}/api/jobs/pdf`, { method: 'POST', headers: auth });
    if (due.pdf) ctx.waitUntil((self ? self.fetch(pdfJobs) : handler.fetch(pdfJobs, env, ctx)).then((r: Response) => r.text()).catch(() => undefined));
    // Turo emails waiting for their car, matched again after the fleet or what was learned changed (0088)
    if (due.turo) run('/api/jobs/turo-rematch');
    // the retention purge of private files (0071), once an hour on the second tick
    if (new Date().getUTCMinutes() >= 5 && new Date().getUTCMinutes() < 10) run('/api/jobs/purge');
    // the usage guard (0080): Cloudflare's figures when the Worker has an analytics token, the alerts, once an hour on the third tick
    if (new Date().getUTCMinutes() >= 10 && new Date().getUTCMinutes() < 15) run('/api/jobs/usage');
  },

  async fetch(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response> {
    const path = new URL(request.url).pathname;
    if (path.startsWith('/media/')) return media(request, env, path);
    // scanners asking for PHP, WordPress or dot files: answered before the app loads (a render costs a second of CPU
    // on a fresh isolate)
    if (isProbe(path)) return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'public, max-age=3600', ...securityHeaders() } });
    if (path === '/api/t' && request.method === 'POST') { const t = await track(request, env, ctx); if (t) return t; }
    // An Admin viewing as someone is read only: every write outside the Admin portal stops here
    // (src/lib/security/view-as-guard.ts). Server actions are POSTs, so this covers all of them.
    if (viewAsWriteRefused(request.method, path, request.headers.get('cookie'))) return viewAsRefusal(request.headers.has('next-action'), securityHeaders());
    // The session is refreshed here, where the response can set the cookie, before a page reads it
    // (src/lib/auth/edge-refresh.ts: a page cannot store a refreshed session, and Supabase then ends it).
    let req = request;
    let setCookies: string[] = [];
    const sbUrl = env.NEXT_PUBLIC_SUPABASE_URL, sbKey = env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
    if (typeof sbUrl === 'string' && typeof sbKey === 'string' && !path.startsWith('/_next/static/')) {
      const r = await refreshSession(request, { url: sbUrl, anonKey: sbKey });
      if (r) { req = r.request; setCookies = r.setCookies; }
    }
    // The Admin portal is always the Admin themselves, even while viewing as someone elsewhere (src/server/view-as.ts).
    if (req.headers.has(ADMIN_AREA_HEADER) || isAdminArea(path)) {
      const h = new Headers(req.headers);
      h.delete(ADMIN_AREA_HEADER);
      if (isAdminArea(path)) h.set(ADMIN_AREA_HEADER, '1');
      req = new Request(req, { headers: h });
    }
    // The public pages the page cache answered before, from this data centre's copy, without loading the app
    // (src/lib/edge/page-cache.ts); what OpenNext answers from its page cache is kept for the next request.
    const version = deploymentOf(env);
    const key = version ? edgeKey(req, version) : null;
    const edge = key ? { cache: () => caches.open(EDGE_CACHE_NAME), env, waitUntil: (p: Promise<unknown>) => ctx.waitUntil(p) } : null;
    let response: Response | null = key && edge ? await edgeMatch(key, edge) : null;
    if (!response) {
      response = (await handler.fetch(req, env, ctx)) as Response;
      if (key && edge) response = edgeKeep(key, path, response, edge);
    }
    const type = response.headers.get('content-type') ?? '';
    const headers = new Headers(response.headers);
    for (const [k, v] of Object.entries(securityHeaders())) headers.set(k, v);
    // the website's schema marker, read by the site check in the database (0063: waiting for the website deploy)
    headers.set(SCHEMA_HEADER, SCHEMA_MARKER);
    for (const c of setCookies) headers.append('set-cookie', c);
    // the email link's outbox row, kept through a sign-in redirect for the beacon (Live visitors, 0060)
    if (request.method === 'GET' && path.startsWith('/account/bookings/')) { const m = emailLinkCookie(request.url, true); if (m) headers.append('set-cookie', m); }
    if (!type.includes('text/html')) return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
    // where the visitor is browsing from (country-region, e.g. CA-ON), for the cookie notice (0075); not stored
    const geo = geoCode((request as Request & { cf?: { country?: string; regionCode?: string } }).cf);
    if (geo && !new RegExp(`(^|;\\s*)cc_geo=${geo}(;|$)`).test(request.headers.get('cookie') ?? '')) {
      headers.append('set-cookie', `cc_geo=${geo}; Path=/; Max-Age=86400; SameSite=Lax${new URL(request.url).protocol === 'https:' ? '; Secure' : ''}`);
    }
    // a page is never reused by the browser without asking first: OpenNext's stale-while-revalidate let Safari show a
    // page kept from a previous deploy, whose style files are gone (home loaded unstyled on phones, Oct 21). The
    // data centre's copy above is unaffected (it is kept before this line).
    headers.set('cache-control', 'no-cache');
    const nonce = newNonce();
    headers.set('Content-Security-Policy', cspHeader(nonce, { turnstile: true }));
    const out = new Response(response.body, { status: response.status, statusText: response.statusText, headers });
    // @ts-expect-error: HTMLRewriter is a Workers global
    return new HTMLRewriter().on('script', new NonceAdder(nonce)).transform(out);
  }
};
export default worker;

/** Cloudflare's country and region for a request, as CA-ON (or CA when the region is unknown); null when unknown. */
function geoCode(cf: { country?: string; regionCode?: string } | undefined): string | null {
  const c = (cf?.country ?? '').toUpperCase();
  if (!/^[A-Z]{2}$/.test(c) || c === 'XX' || c === 'T1') return null;
  const r = (cf?.regionCode ?? '').toUpperCase();
  return /^[A-Z0-9]{1,3}$/.test(r) ? `${c}-${r}` : c;
}

